#!/usr/bin/env python3
"""Colab Phase 1 bootstrap — self-contained.
Writes source, installs deps, runs tests.
"""
import subprocess, sys, os

def run(cmd, desc="", check=True):
    print(f"\n>>> {desc or cmd}")
    r = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    if check and r.returncode != 0:
        print(f"FAILED: {cmd}\n{r.stderr[:500]}")
        sys.exit(1)
    out = r.stdout.strip()
    if out:
        print(out[:500])
    return r

# GPU check
r = run("nvidia-smi --query-gpu=name --format=csv,noheader", check=False)
print(f"GPU: {r.stdout.strip()}")

# Python version
r = run("python3 -c 'import sys; print(sys.version)'")
print(r.stdout.strip())

# Install deps
run("pip install -q numpy soundfile librosa scipy jiwer pyyaml einops huggingface-hub phonemizer speechbrain faster-whisper pytest")

# Clone repos
run("git clone --depth 1 https://github.com/Claussss/FAC-FACodec.git /content/FAC-FACodec")

# Write source files
