DIFFUSION_CODE = '"""Phase 1 -- Diffusion math: noise schedule, sampling, strength mapping."""\nfrom __future__ import annotations\n\nimport torch\n\n\ndef compute_noise_schedule(num_steps: int = 100, noise_min: float = 1e-4, noise_max: float = 2e-2):\n    betas = torch.linspace(noise_min, noise_max, num_steps)\n    alphas = 1.0 - betas\n    alpha_bar = torch.cumprod(alphas, dim=0)\n    return {\n        "betas": betas, "alphas": alphas, "alpha_bar": alpha_bar,\n        "sqrt_alpha_bar": torch.sqrt(alpha_bar),\n        "sqrt_1m_alpha_bar": torch.sqrt(1.0 - alpha_bar),\n    }\n\n\ndef q_sample(x0, t, sqrt_alpha_bar, sqrt_1m_alpha_bar):\n    noise = torch.randn_like(x0)\n    xt = sqrt_alpha_bar[t].view(-1, 1, 1) * x0 + sqrt_1m_alpha_bar[t].view(-1, 1, 1) * noise\n    return xt, noise\n\n\ndef ddim_step(x_t, eps_pred, t, t_prev, sqrt_alpha_bar, sqrt_1m_alpha_bar, eta: float = 0.0):\n    bsz = x_t.size(0)\n    sqrt_a_t = sqrt_alpha_bar[t].view(-1, 1, 1)\n    sqrt_1ma_t = sqrt_1m_alpha_bar[t].view(-1, 1, 1)\n    x0_pred = (x_t - sqrt_1ma_t * eps_pred) / sqrt_a_t\n    x0_pred = torch.clamp(x0_pred, -10, 10)\n    if t_prev is None:\n        return x0_pred\n    t_prev_int = int(t_prev) if not isinstance(t_prev, int) else t_prev\n    if t_prev_int < 0:\n        return x0_pred\n    sqrt_a_prev = sqrt_alpha_bar[t_prev].view(-1, 1, 1)\n    sqrt_1ma_prev = sqrt_1m_alpha_bar[t_prev].view(-1, 1, 1)\n    noise = torch.randn_like(x_t)\n    x_t = sqrt_a_prev * x0_pred + sqrt_1ma_prev * eps_pred + eta * sqrt_1ma_prev * noise\n    return x_t\n\n\ndef strength_to_t_start(strength: float, num_steps: int = 100) -> int:\n    strength = max(0.0, min(1.0, strength))\n    return int(round(strength * num_steps))\n\n\ndef t_start_to_strength(t_start: int, num_steps: int = 100) -> float:\n    return t_start / max(1, num_steps)\n'
with open("/content/accentedge/src/accentedge/phase1/diffusion.py", "w") as f:
    f.write(DIFFUSION_CODE)

DENOISER_CODE = '"""Phase 1 -- FAC-FACodec denoiser (paper-faithful reimplementation).\n\nPaper: arxiv:2510.10785\nReference impl: Claussss/FAC-FACodec (MIT License)\n"""\nfrom __future__ import annotations\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\nfrom dataclasses import dataclass\nfrom typing import Optional, List\n\n\nclass StrengthScheduler:\n    """Maps strength [0,1] to diffusion timestep."""\n\n    def __init__(self, num_steps: int = 100, schedule: str = "linear"):\n        self.num_steps = num_steps\n        self.schedule = schedule\n\n    def __call__(self, strength: float) -> int:\n        strength = max(0.0, min(1.0, strength))\n        return int(round(strength * self.num_steps))\n\n    def validate(self, strength: float) -> bool:\n        return 0.0 <= strength <= 1.0\n\n    def available_strengths(self) -> List[float]:\n        return [0.0, 0.25, 0.50, 0.75, 1.0]\n\n\n@dataclass\nclass DenoisingResult:\n    original: torch.Tensor\n    denoised: torch.Tensor\n    strength: float\n    timesteps_used: int\n    converged: bool\n\n\nclass SinusoidalPosEmb(nn.Module):\n    """Sinusoidal positional embedding for diffusion timesteps."""\n    def __init__(self, dim: int):\n        super().__init__()\n        self.dim = dim\n\n    def forward(self, t: torch.Tensor) -> torch.Tensor:\n        half_dim = self.dim // 2\n        emb = torch.log(torch.tensor(10000.0)) / (half_dim - 1)\n        emb = torch.exp(torch.arange(half_dim, device=t.device) * -emb)\n        emb = t[:, None] * emb[None, :]\n        emb = torch.cat([torch.sin(emb), torch.cos(emb)], dim=-1)\n        return emb\n\n\nclass CondLayerNorm(nn.Module):\n    """Conditional LayerNorm with FiLM-style affine modulation.\n\n    cond is [B, T, 2D], split into gamma and beta.\n    Output: x_norm * (1 + gamma) + beta\n    """\n    def __init__(self, d_model: int):\n        super().__init__()\n        self.norm = nn.LayerNorm(d_model, elementwise_affine=False)\n\n    def forward(self, x: torch.Tensor, cond: torch.Tensor) -> torch.Tensor:\n        gamma, beta = cond.chunk(2, dim=-1)\n        x_norm = self.norm(x)\n        return x_norm * (1 + gamma) + beta\n\n\nclass ConvFeedForward(nn.Module):\n    """1D convolution FFN block (matches paper implementation)."""\n    def __init__(self, d_model: int = 1024, d_ff: int = 2048, kernel_size: int = 3, dropout: float = 0.1):\n        super().__init__()\n        self.conv1 = nn.Conv1d(d_model, d_ff, kernel_size, padding=(kernel_size // 2))\n        self.conv2 = nn.Conv1d(d_ff, d_model, kernel_size, padding=(kernel_size // 2))\n        self.dropout = nn.Dropout(dropout)\n        self.relu = nn.ReLU()\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        out = self.conv1(x)\n        out = self.relu(out)\n        out = self.dropout(out)\n        out = self.conv2(out)\n        return self.dropout(out)\n\n\nclass CustomTransformerEncoderLayer(nn.Module):\n    """Transformer encoder layer with ConvFFN and conditional LayerNorm (FiLM)."""\n    def __init__(self, d_model: int = 1024, nhead: int = 8, d_ff: int = 2048, dropout: float = 0.1):\n        super().__init__()\n        self.self_attn = nn.MultiheadAttention(d_model, nhead, dropout=dropout, batch_first=True)\n        self.norm1 = nn.LayerNorm(d_model)\n        self.norm2 = CondLayerNorm(d_model)\n        self.dropout = nn.Dropout(dropout)\n        self.conv_ff = ConvFeedForward(d_model=d_model, d_ff=d_ff, kernel_size=3, dropout=dropout)\n\n    def forward(\n        self,\n        x: torch.Tensor,\n        cond: torch.Tensor,\n        src_key_padding_mask: Optional[torch.BoolTensor] = None,\n    ) -> torch.Tensor:\n        # Self-attention block\n        attn_out, _ = self.self_attn(x, x, x, key_padding_mask=src_key_padding_mask)\n        x = x + self.dropout(attn_out)\n        x = self.norm1(x)\n\n        # Conv feed-forward block\n        x_t = x.transpose(1, 2)  # [B, D, T]\n        ff_out = self.conv_ff(x_t)\n        ff_out = ff_out.transpose(1, 2)  # [B, T, D]\n        x = x + self.dropout(ff_out)\n\n        # Conditional LayerNorm with FiLM parameters\n        return self.norm2(x, cond)\n\n\nclass CustomTransformerEncoder(nn.Module):\n    """Stacks multiple Conditional Transformer encoder layers."""\n    def __init__(self, num_layers: int = 6, d_model: int = 1024, nhead: int = 8, d_ff: int = 2048, dropout: float = 0.1):\n        super().__init__()\n        self.layers = nn.ModuleList([\n            CustomTransformerEncoderLayer(d_model, nhead, d_ff, dropout)\n            for _ in range(num_layers)\n        ])\n\n    def forward(\n        self,\n        x: torch.Tensor,\n        cond: torch.Tensor,\n        src_key_padding_mask: Optional[torch.BoolTensor] = None,\n    ) -> torch.Tensor:\n        for layer in self.layers:\n            x = layer(x, cond, src_key_padding_mask)\n        return x\n\n\nclass DenoisingTransformerModel(nn.Module):\n    """FAC-FACodec denoiser: 6-layer Transformer, 8 heads, dim=1024, FFN=2048.\n\n    Predicts epsilon noise and zc2 from denoised x0 estimate.\n    Conditioned on phoneme embeddings + timestep via FiLM.\n    """\n    def __init__(\n        self,\n        d_model: int = 1024,\n        nhead: int = 8,\n        num_layers: int = 6,\n        d_ff: int = 2048,\n        dropout: float = 0.1,\n        phone_vocab_size: int = 393,\n        phone_pad_id: int = 392,\n        num_steps: int = 100,\n        facodec_dim: int = 8,\n    ):\n        super().__init__()\n        self.num_steps = num_steps\n        self.d_model = d_model\n        self.facodec_dim = facodec_dim\n\n        # Timestep embedding (sinusoidal)\n        self.t_embed = nn.Sequential(\n            SinusoidalPosEmb(d_model),\n            nn.Linear(d_model, d_model * 2),\n            nn.SiLU(),\n            nn.Linear(d_model * 2, d_model * 2),\n        )\n\n        # Phoneme embedding\n        self.phone_emb = nn.Embedding(phone_vocab_size, d_model, padding_idx=phone_pad_id)\n\n        # Input projection: [B, C, T] -> [B, T, D]\n        self.input_proj = nn.Linear(facodec_dim, d_model)\n\n        # Custom encoder with conditional LayerNorm\n        self.encoder = CustomTransformerEncoder(\n            num_layers=num_layers, d_model=d_model, nhead=nhead,\n            d_ff=d_ff, dropout=dropout,\n        )\n\n        # Epsilon prediction head\n        self.fc_out = nn.Linear(d_model, facodec_dim)\n\n        # Zc2 prediction head\n        self.fc_zc2 = nn.Sequential(\n            nn.Linear(d_model + facodec_dim, 4 * facodec_dim),\n            nn.GELU(),\n            nn.Linear(4 * facodec_dim, facodec_dim),\n        )\n\n        # FiLM conditioning\n        self.phone_proj = nn.Linear(d_model, d_model * 2)\n        self.dropout = nn.Dropout(dropout)\n\n        # DDPM schedule buffers\n        betas = torch.linspace(1e-4, 0.02, num_steps, dtype=torch.float)\n        alphas = 1.0 - betas\n        abar = torch.cumprod(alphas, dim=0)\n        self.register_buffer("sqrt_abar", torch.sqrt(abar))\n        self.register_buffer("sqrt_1mabar", torch.sqrt(1.0 - abar))\n\n    def forward(\n        self,\n        zc1_noisy: torch.Tensor,        # [B, C, T]\n        phone_ids: torch.Tensor,         # [B, T]\n        t: torch.Tensor,                 # [B]\n        padding_mask: Optional[torch.BoolTensor] = None,\n    ) -> tuple[torch.Tensor, torch.Tensor]:\n        bsz, feat_dim, seq_len = zc1_noisy.shape\n\n        # Input projection: [B, C, T] -> [B, T, D]\n        h = self.input_proj(zc1_noisy.transpose(1, 2))\n\n        # Phoneme conditioning\n        phone_emb = self.phone_emb(phone_ids)                        # [B, T, D]\n        phone_cond = self.phone_proj(phone_emb)                      # [B, T, 2D]\n\n        # Timestep conditioning\n        t_emb = self.t_embed(t)                                      # [B, 2D]\n        t_cond = t_emb.unsqueeze(1).expand(-1, seq_len, -1)         # [B, T, 2D]\n        cond = self.dropout(phone_cond) + t_cond                     # [B, T, 2D]\n\n        # Encode\n        h = self.encoder(h, cond, src_key_padding_mask=padding_mask)\n\n        # Epsilon prediction: [B, T, D] -> [B, C, T]\n        eps_pred = self.fc_out(h).transpose(1, 2)\n\n        # Zc2 prediction from denoised x0 estimate\n        sa = self.sqrt_abar[t].view(bsz, 1, 1)\n        s1a = self.sqrt_1mabar[t].view(bsz, 1, 1)\n        x0_hat = (zc1_noisy - s1a * eps_pred.detach()) / sa\n\n        zc2_input = torch.cat([h, x0_hat.detach().transpose(1, 2)], dim=-1)\n        zc2_pred = self.fc_zc2(zc2_input).transpose(1, 2)\n\n        # Return shapes [B, C, T]\n        return eps_pred, zc2_pred\n\n\nclass Phase1AccentNormalizer(nn.Module):\n    """Minimal Phase-1 module: denoiser only.\n\n    Only the denoiser weights are trainable. Everything else is frozen.\n    """\n    def __init__(self, denoiser: nn.Module, num_steps: int = 100,\n                 facodec_dim: int = 8, device: str = "cpu"):\n        super().__init__()\n        self.denoiser = denoiser\n        self.num_steps = num_steps\n        self.facodec_dim = facodec_dim\n        self.device = torch.device(device)\n        self.denoiser.to(self.device)\n\n    def forward(self, zc1: torch.Tensor, phone_ids: torch.Tensor, t: torch.Tensor,\n                padding_mask: Optional[torch.BoolTensor] = None):\n        return self.denoiser(zc1, phone_ids, t, padding_mask)\n'
with open("/content/accentedge/src/accentedge/phase1/denoiser.py", "w") as f:
    f.write(DENOISER_CODE)

STRENGTH_CODE = '"""Phase 1 — Conversion strength control.\n\nMaps user-facing strength ∈ [0, 1] to paper-native t_start timestep.\n\nstrength=0.0 → t_start=0 (no accent normalization)\nstrength=1.0 → t_start=num_steps (maximum normalization)\n"""\nfrom __future__ import annotations\n\nimport torch\n\n\ndef strength_to_t_start(strength: float, num_steps: int = 100) -> int:\n    """Map conversion strength ∈ [0, 1] to diffusion timestep."""\n    strength = max(0.0, min(1.0, strength))\n    return int(round(strength * num_steps))\n\n\ndef t_start_to_strength(t_start: int, num_steps: int = 100) -> float:\n    """Inverse mapping."""\n    return t_start / max(1, num_steps)\n\n\nclass StrengthScheduler:\n    """Maps strength to diffusion timestep with configurable schedule."""\n\n    def __init__(self, num_steps: int = 100, schedule: str = "linear"):\n        self.num_steps = num_steps\n        self.schedule = schedule\n\n    def __call__(self, strength: float) -> int:\n        return strength_to_t_start(strength, self.num_steps)\n\n    def validate(self, strength: float) -> bool:\n        return 0.0 <= strength <= 1.0\n\n    def available_strengths(self) -> list:\n        return [0.0, 0.25, 0.50, 0.75, 1.0]\n'
with open("/content/accentedge/src/accentedge/phase1/strength.py", "w") as f:
    f.write(STRENGTH_CODE)

FACODEC_CODE = '"""Phase 1 — FACodec adapter (using standalone Plachta/FAcodec).\n\nWraps Plachta/FAcodec (NaturalSpeech 3 factorized codec) as AccentEdge\'s\nfrozen codec backend. The codec is frozen after initialization.\n\nKey verified facts:\n  - Sample rate: 24000 Hz\n  - Content: zc1 (2 codebooks, dim=8) + zc2 (predicted after denoising)\n  - Prosody: zp (1 codebook, dim=8)\n  - Acoustic detail: zr (3 codebooks, dim=8) — residual after content+prosody+timbre\n  - Timbre: g (single vector per utterance, dim=1024)\n  - Frame rate: 50 fps (hop_length=300 at 24kHz)\n  - Codebook: 1024 entries, 8-dim each\n\nUpstream: https://github.com/Plachtaa/FAcodec\nCheckpoint: Plachta/FAcodec (HuggingFace)\n"""\nfrom __future__ import annotations\n\nimport os\nimport sys\nimport hashlib\nimport warnings\nfrom pathlib import Path\nfrom typing import Optional\n\nimport torch\nimport torch.nn as nn\nimport numpy as np\nimport soundfile as sf\nimport yaml\n\nwarnings.simplefilter("ignore")\n\n# Path to standalone FAcodec repo (verified working)\n_FACODEC_REPO = Path(__file__).resolve().parents[3] / ".." / "FAcodec"\n_FACODEC_REPO = _FACODEC_REPO.resolve()\n\nif str(_FACODEC_REPO) not in sys.path:\n    sys.path.insert(0, str(_FACODEC_REPO))\n\nfrom codec.interfaces import FactorizedLatents, FactorizedSpeechCodec\n\n\nclass FACodecAdapter(nn.Module, FactorizedSpeechCodec):\n    """Wraps Plachta/FAcodec as AccentEdge\'s frozen codec.\n\n    Usage:\n        adapter = FACodecAdapter(device="cpu")\n        latents = adapter.encode(waveform)\n        recon = adapter.decode(latents)\n    """\n\n    sample_rate: int = 24000\n\n    def __init__(self, device: str = "cpu", facodec_ckpt: str = "Plachta/FAcodec"):\n        super().__init__()\n        self.device = torch.device(device)\n\n        # Import FAcodec modules\n        from modules.commons import build_model, recursive_munch\n        from hf_utils import load_custom_model_from_hf\n\n        ckpt_path, config_path = load_custom_model_from_hf(facodec_ckpt)\n        with open(config_path) as f:\n            config = yaml.safe_load(f)\n\n        model_params = recursive_munch(config.get("model_params", config.get("model", {})))\n        self.model = build_model(model_params)\n\n        ckpt_params = torch.load(ckpt_path, map_location="cpu")\n        for key in ckpt_params:\n            self.model[key].load_state_dict(ckpt_params[key])\n\n        # Move all sub-models to device\n        for key in self.model:\n            self.model[key].eval().to(self.device)\n\n        # Freeze all parameters\n        if True:  # freeze_codec flag\n            for key in self.model:\n                for param in self.model[key].parameters():\n                    param.requires_grad = False\n\n        # Cache config\n        self._config_hash = hashlib.sha256(\n            yaml.dump(model_params).encode()\n        ).hexdigest()[:16]\n\n        self._ckpt_hash = hashlib.sha256(\n            open(ckpt_path, "rb").read()\n        ).hexdigest()[:16]\n\n    # ──────────────────────────────────────────────────────────────────────────\n    # Encode / decode\n    # ──────────────────────────────────────────────────────────────────────────\n\n    @torch.no_grad()\n    def encode(self, waveform: torch.Tensor) -> FactorizedLatents:\n        """Encode waveform → factorized latents.\n\n        Args:\n            waveform: [B, T] float32, range [-1, 1], sample_rate=24000\n\n        Returns:\n            FactorizedLatents with content (zc1 continuous), prosody, timbre\n        """\n        if waveform.dim() == 1:\n            waveform = waveform.unsqueeze(0)\n\n        z = self.model.encoder(waveform[None, ...].to(self.device).float())\n        _, quantized, _, _, timbre, codes = self.model.quantizer(\n            z, waveform[None, ...].to(self.device).float(), return_codes=True, n_c=2\n        )\n\n        # codes: [codes_c, codes_p, codes_t, codes_r]\n        # quantized: [z_c, z_p, z_t, z_r]\n        codes_c, codes_p, codes_t, codes_r = codes\n        z_c, z_p, z_t, z_r = quantized\n\n        # z_c is [z_c1 + z_c2]; we need z_c1 separately\n        # The quantizer returns the combined content; split into codebooks\n        # codes_c[0] = zc1 indices, codes_c[1] = zc2 indices\n        return FactorizedLatents(\n            content=z_c,  # combined content [B, D, T]\n            content_zc1=codes_c[0] if isinstance(codes_c, (list, tuple)) else codes_c,\n            content_zc2=codes_c[1] if isinstance(codes_c, (list, tuple)) and len(codes_c) > 1 else None,\n            prosody=codes_p,\n            detail=codes_r,\n            timbre=timbre,\n            metadata={\n                "sample_rate": self.sample_rate,\n                "codec_hash": self._ckpt_hash,\n                "config_hash": self._config_hash,\n                "source_shape": list(waveform.shape),\n            },\n        )\n\n    @torch.no_grad()\n    def decode(self, latents: FactorizedLatents) -> torch.Tensor:\n        """Decode factorized latents → waveform.\n\n        Reconstructs from content + prosody + timbre.\n        zc2 is zeroed (not available during conversion in Phase 1).\n        """\n        # Convert zc1 codes to continuous vectors\n        z_c = self._codes_to_vector(latents.content_zc1, quantizer_idx=1, layer=0)  # [B, D, T]\n\n        z = z_c\n        if latents.prosody is not None:\n            z_p = self._codes_to_vector(latents.prosody, quantizer_idx=0, layer=0)\n            z = z + z_p\n\n        # Timbre: add if available\n        if latents.timbre is not None:\n            # Timbre is a global vector [B, D]; expand to sequence\n            # In the full codec, timbre conditions the decoder\n            # For Phase 1, we add it as a mean offset\n            timbre_mean = latents.timbre.mean(dim=-1, keepdim=True).unsqueeze(-1)  # [B, D, 1]\n            z = z + timbre_mean\n\n        with torch.no_grad():\n            waveform = self.model.decoder(z.to(self.device))\n        return waveform.cpu()\n\n    def _codes_to_vector(self, code_indices, quantizer_idx: int = 0, layer: int = 0) -> torch.Tensor:\n        """Convert codebook indices to continuous latent vectors."""\n        codebook = self.model.quantizer[quantizer_idx].layers[layer].codebook.weight\n        z = torch.nn.functional.embedding(code_indices.squeeze(0), codebook)\n        z = z.transpose(1, 2).unsqueeze(0)  # [B, D, T]\n        # Apply output projection if present\n        if hasattr(self.model.quantizer[quantizer_idx].layers[layer], \'out_proj\'):\n            z = self.model.quantizer[quantizer_idx].layers[layer].out_proj(z)\n        return z\n\n    @torch.no_grad()\n    def reconstruction(self, waveform: torch.Tensor) -> torch.Tensor:\n        """Baseline: encode → decode without modification."""\n        latents = self.encode(waveform)\n        return self.decode(latents)\n\n    def freeze(self) -> None:\n        """Assert all codec parameters are frozen."""\n        frozen = True\n        for key in self.model:\n            for param in self.model[key].parameters():\n                if param.requires_grad:\n                    frozen = False\n                    print(f"WARNING: {key} parameter still requires_grad!")\n        assert frozen, "FACodec parameters must be frozen in Phase 1"\n        print("FACodec: all parameters frozen ✓")\n'
with open("/content/accentedge/src/accentedge/codec/facodec.py", "w") as f:
    f.write(FACODEC_CODE)

INTERFACES_CODE = '"""Phase 1 — Factorized speech codec interface.\n\nAccentEdge does not permanently couple to one upstream codec implementation.\nThis module defines the internal abstraction.\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Optional\n\nimport torch\n\n\n@dataclass\nclass FactorizedLatents:\n    """Container for factorized speech representations.\n\n    Attributes correspond to FAC-FACodec verified factorization:\n      content:    z_c1 + z_c2 (quantized content residual)\n      content_zc1: z_c1 (8-dim quantized content codebook indices)\n      content_zc2: z_c2 (content residual, predicted after denoising)\n      prosody:    z_p (prosody codebook indices)\n      detail:     z_r (residual acoustic detail codebook indices)\n      timbre:     g (global timbre embedding, one vector per utterance)\n      metadata:   arbitrary per-frame/per-utterance metadata\n    """\n    content: torch.Tensor          # [B, C, T] quantized content representation\n    content_zc1: torch.Tensor      # [B, 1, T] codebook indices for z_c1\n    content_zc2: Optional[torch.Tensor] = None  # [B, C2, T] codebook indices for z_c2\n    prosody: Optional[torch.Tensor] = None       # [B, 1, T] codebook indices\n    detail: Optional[torch.Tensor] = None        # [B, K, T] codebook indices for residual\n    timbre: Optional[torch.Tensor] = None        # [B, D] global timbre vector\n    metadata: dict = field(default_factory=dict)\n\n\nclass FactorizedSpeechCodec:\n    """Protocol for factorized speech codecs.\n\n    All implementations must:\n      1. Freeze codec parameters after initialization\n      2. Provide encode/decode round-trip\n      3. Expose sample_rate\n    """\n\n    sample_rate: int\n\n    def encode(self, waveform: torch.Tensor) -> FactorizedLatents:\n        """Encode waveform → factorized latents."""\n        ...\n\n    def decode(self, latents: FactorizedLatents) -> torch.Tensor:\n        """Decode factorized latents → waveform."""\n        ...\n\n    def freeze(self) -> None:\n        """Freeze all codec parameters."""\n        for param in self.parameters():\n            param.requires_grad = False\n\n    def parameters(self):\n        """Yield all parameters."""\n        ...\n'
with open("/content/accentedge/src/accentedge/codec/interfaces.py", "w") as f:
    f.write(INTERFACES_CODE)

IDENTITY_CODE = '"""Phase 1 — Speaker identity evaluation.\n\nUses SpeechBrain ECAPA-TDNN (spkrec-ecapa-voxceleb) for speaker embedding.\n\nKey Phase-1 quantity:\n  identity_drop(strength) = sim(source, reconstruction) - sim(source, converted)\n"""\nfrom __future__ import annotations\n\nimport numpy as np\nimport torch\nimport soundfile as sf\n\n\nclass IdentityEvaluator:\n    """ECAPA-TDNN speaker similarity evaluator."""\n\n    def __init__(self, device: str = "cpu"):\n        from speechbrain.pretrained import EncoderClassifier\n        self.classifier = EncoderClassifier.from_hparams(\n            source="speechbrain/spkrec-ecapa-voxceleb",\n            savedir="/tmp/spkrec_ecapa",\n        )\n        self.device = device\n\n    @torch.no_grad()\n    def embed(self, waveform: np.ndarray, sr: int = 24000) -> torch.Tensor:\n        """Compute speaker embedding for a waveform."""\n        if waveform.ndim > 1:\n            waveform = waveform.mean(axis=1)\n        wav_t = torch.tensor(waveform, dtype=torch.float32).unsqueeze(0)\n        emb = self.classifier.encode_batch(wav_t)\n        return (emb / emb.norm(dim=-1, keepdim=True)).squeeze()\n\n    def similarity(self, src: np.ndarray, tgt: np.ndarray, sr: int = 24000) -> float:\n        """Cosine similarity between two waveforms."""\n        emb_src = self.embed(src, sr)\n        emb_tgt = self.embed(tgt, sr)\n        return float(torch.dot(emb_src, emb_tgt).item())\n\n    def identity_drop(self, source: np.ndarray, reconstruction: np.ndarray,\n                      converted: np.ndarray, sr: int = 24000) -> dict:\n        """Compute identity drop relative to reconstruction ceiling."""\n        sim_recon = self.similarity(source, reconstruction, sr)\n        sim_conv = self.similarity(source, converted, sr)\n        return {\n            "sim_reconstruction": sim_recon,\n            "sim_converted": sim_conv,\n            "identity_drop": sim_recon - sim_conv,\n        }\n'
with open("/content/accentedge/src/accentedge/evaluation/identity.py", "w") as f:
    f.write(IDENTITY_CODE)

CONTENT_CODE = '"""Phase 1 — Content evaluation.\n\nMetrics:\n  - WER (via Faster-Whisper ASR)\n  - CER (character error rate)\n  - Content preservation ratio\n"""\nfrom __future__ import annotations\n\nimport numpy as np\nfrom jiwer import wer, cer\n\n\ndef compute_wer(reference: str, hypothesis: str) -> float:\n    return wer(reference, hypothesis)\n\n\ndef compute_cer(reference: str, hypothesis: str) -> float:\n    return cer(reference, hypothesis)\n\n\ndef compute_content_metrics(reference: str, hypothesis: str) -> dict:\n    """Compute content preservation metrics for a single utterance."""\n    return {\n        "wer": compute_wer(reference, hypothesis),\n        "cer": compute_cer(reference, hypothesis),\n        "reference": reference,\n        "hypothesis": hypothesis,\n    }\n\n\nclass ContentEvaluator:\n    """Batch content evaluation using WER/CER."""\n\n    def __init__(self):\n        self.results: list[dict] = []\n\n    def evaluate(self, reference: str, hypothesis: str) -> dict:\n        result = compute_content_metrics(reference, hypothesis)\n        self.results.append(result)\n        return result\n\n    def summary(self) -> dict:\n        if not self.results:\n            return {"mean_wer": 0.0, "mean_cer": 0.0, "n_samples": 0}\n        return {\n            "mean_wer": float(np.mean([r["wer"] for r in self.results])),\n            "mean_cer": float(np.mean([r["cer"] for r in self.results])),\n            "n_samples": len(self.results),\n        }\n'
with open("/content/accentedge/src/accentedge/evaluation/content.py", "w") as f:
    f.write(CONTENT_CODE)

ACOUSTIC_CODE = '"""Phase 1 — Acoustic quality evaluation.\n\nHonest metrics — no fabricated "speaker similarity" from mel statistics.\n"""\nfrom __future__ import annotations\n\nimport numpy as np\nimport torch\nimport torch.nn.functional as F\n\n\ndef mel_spectrogram(waveform: np.ndarray, sr: int = 24000, n_fft: int = 2048,\n                    hop_length: int = 300, n_mels: int = 80) -> np.ndarray:\n    """Compute mel spectrogram (numpy, for evaluation only)."""\n    import librosa\n    mel = librosa.feature.melspectrogram(\n        y=waveform, sr=sr, n_fft=n_fft, hop_length=hop_length, n_mels=n_mels\n    )\n    mel_db = librosa.power_to_db(mel, ref=np.max)\n    return mel_db\n\n\ndef mel_l1(source: np.ndarray, target: np.ndarray, sr: int = 24000) -> float:\n    """Mean absolute difference between mel spectrograms."""\n    mel_src = mel_spectrogram(source, sr)\n    mel_tgt = mel_spectrogram(target, sr)\n    # Align lengths\n    min_len = min(mel_src.shape[1], mel_tgt.shape[1])\n    diff = np.abs(mel_src[:, :min_len] - mel_tgt[:, :min_len])\n    return float(diff.mean())\n\n\ndef duration_ratio(source: np.ndarray, target: np.ndarray, sr: int = 24000) -> float:\n    """Ratio of output duration to source duration."""\n    return len(target) / max(len(source), 1)\n\n\nclass AcousticEvaluator:\n    """Acoustic quality diagnostics."""\n\n    def __init__(self, sr: int = 24000):\n        self.sr = sr\n\n    def evaluate(self, source: np.ndarray, target: np.ndarray) -> dict:\n        return {\n            "mel_l1": mel_l1(source, target, self.sr),\n            "duration_ratio": duration_ratio(source, target, self.sr),\n        }\n'
with open("/content/accentedge/src/accentedge/evaluation/acoustic.py", "w") as f:
    f.write(ACOUSTIC_CODE)

